--[[
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local CoreGui = game:GetService("CoreGui")
local UserInputService = game:GetService("UserInputService")

local isPCMode = getgenv().Script_Mode == "PC"

--// Restricted PlaceId Check
if game.PlaceId == 93978595733734 then
    local Invisible = nil
    local invis_on = false
    local invisGui = nil
    local invisLoading = true
    local isLocked = false

    --// 1. Cleanup
    local function forceCleanupInvisible()
        pcall(function()
            local chair = workspace:FindFirstChild("invischair")
            if chair then
                chair:Destroy()
            end

            local char = LocalPlayer.Character
            if char then
                for _, part in pairs(char:GetDescendants()) do
                    if part:IsA("BasePart") or part:IsA("Decal") then
                        if part.Name ~= "Hurtbox"
                            and part.Name ~= "HumanoidRootPart"
                            and part.Name ~= "HRP_Clone" then
                            part.Transparency = 0
                        end
                    end
                end
            end
        end)
    end

    --// 2. Update Original Button
    local function updateInvisButton()
        if not invisGui then return end

        local btn = invisGui:FindFirstChild("InvisButton")
        if not btn then return end

        local stroke = btn:FindFirstChildOfClass("UIStroke")

        if invis_on then
            btn.Text = "INVISIBLE: ON"
            btn.TextColor3 = Color3.fromRGB(0, 255, 127)

            if stroke then
                stroke.Color = Color3.fromRGB(0, 255, 127)
            end
        else
            btn.Text = "INVISIBLE: OFF"
            btn.TextColor3 = Color3.fromRGB(200, 200, 200)

            if stroke then
                stroke.Color = Color3.fromRGB(60, 60, 60)
            end
        end
    end

    --// 3. Toggle Invisible
    local function setInvisibleState(state)
        if not Invisible then return end

        invis_on = state

        if state then
            local ok = pcall(function()
                Invisible.enable()
            end)

            if not ok then
                forceCleanupInvisible()
            end
        else
            pcall(function()
                Invisible.disable()
            end)

            forceCleanupInvisible()
        end

        updateInvisButton()
    end

    --// 4. Original Toggle Button & Lock Button
    local function createInvisButton()
        local existing = CoreGui:FindFirstChild("InvisButtonGui")
        if existing then
            existing:Destroy()
        end

        local gui = Instance.new("ScreenGui")
        gui.Name = "InvisButtonGui"
        gui.ResetOnSpawn = false
        gui.Parent = CoreGui

        local btn = Instance.new("TextButton")
        btn.Name = "InvisButton"
        btn.Size = UDim2.fromOffset(130, 35)
        btn.Position = UDim2.new(0.5, -65, 0.05, 0)
        btn.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
        btn.Text = "INVISIBLE: OFF"
        btn.TextColor3 = Color3.fromRGB(200, 200, 200)
        btn.Font = Enum.Font.GothamBold
        btn.TextSize = 12
        btn.Parent = gui

        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 8)

        local stroke = Instance.new("UIStroke", btn)
        stroke.Color = Color3.fromRGB(60, 60, 60)
        stroke.Thickness = 1.5

        local lockBtn = Instance.new("TextButton")
        lockBtn.Name = "LockButton"
        lockBtn.Size = UDim2.fromOffset(30, 30)
        lockBtn.Position = UDim2.new(1, -40, 1, -40)
        lockBtn.BackgroundColor3 = Color3.fromRGB(35, 35, 35)
        lockBtn.Text = "🔓"
        lockBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        lockBtn.Font = Enum.Font.GothamBold
        lockBtn.TextSize = 14
        lockBtn.Parent = gui

        Instance.new("UICorner", lockBtn).CornerRadius = UDim.new(0, 6)

        local lockStroke = Instance.new("UIStroke", lockBtn)
        lockStroke.Color = Color3.fromRGB(80, 80, 80)
        lockStroke.Thickness = 1.5

        local dragging, dragStart, startPos

        btn.InputBegan:Connect(function(input)
            if isLocked then return end

            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then

                dragging = true
                dragStart = input.Position
                startPos = btn.Position

                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                    end
                end)
            end
        end)

        UserInputService.InputChanged:Connect(function(input)
            if dragging and not isLocked
                and (input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch) then

                local delta = input.Position - dragStart

                btn.Position = UDim2.new(
                    startPos.X.Scale,
                    startPos.X.Offset + delta.X,
                    startPos.Y.Scale,
                    startPos.Y.Offset + delta.Y
                )
            end
        end)

        lockBtn.MouseButton1Click:Connect(function()
            isLocked = not isLocked

            if isLocked then
                lockBtn.Text = "🔒"
                lockBtn.TextColor3 = Color3.fromRGB(255, 100, 100)
                lockStroke.Color = Color3.fromRGB(255, 100, 100)
            else
                lockBtn.Text = "🔓"
                lockBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                lockStroke.Color = Color3.fromRGB(80, 80, 80)
            end
        end)

        btn.MouseButton1Click:Connect(function()
            if not invisLoading then
                setInvisibleState(not invis_on)
            end
        end)

        invisGui = gui
    end

    --// 5. Load Invisible API
    local function loadInvisibleAPI()
        task.spawn(function()
            if not _G.MengHub or not _G.MengHub.Invisible then
                pcall(function()
                    loadstring(game:HttpGet(
                        "https://leekguy.vercel.app/roblox/menghub/crack_obf_invisible_93978595733734.lua"
                    ))()
                end)
            end

            Invisible = _G.MengHub and _G.MengHub.Invisible
            invisLoading = false
        end)

        -- PC Mode does not create the original floating GUI
        if not isPCMode then
            createInvisButton()
        end
    end

    --// 6. PC Guide GUI
    local function showPCGuide()
        local oldGui = CoreGui:FindFirstChild("InvisPCGuide")
        if oldGui then
            oldGui:Destroy()
        end

        local gui = Instance.new("ScreenGui")
        gui.Name = "InvisPCGuide"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 999
        gui.Parent = CoreGui

        local frame = Instance.new("Frame")
        frame.Name = "Main"
        frame.Size = UDim2.fromOffset(360, 190)
        frame.Position = UDim2.fromScale(0.5, 0.5)
        frame.AnchorPoint = Vector2.new(0.5, 0.5)
        frame.BackgroundColor3 = Color3.fromRGB(20, 22, 30)
        frame.BorderSizePixel = 0
        frame.Parent = gui

        Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 14)

        local frameStroke = Instance.new("UIStroke", frame)
        frameStroke.Color = Color3.fromRGB(0, 190, 140)
        frameStroke.Thickness = 1.5

        local title = Instance.new("TextLabel")
        title.Name = "Title"
        title.Size = UDim2.new(1, -30, 0, 35)
        title.Position = UDim2.fromOffset(15, 12)
        title.BackgroundTransparency = 1
        title.Text = "REAPER  |  INVISIBLE"
        title.TextColor3 = Color3.fromRGB(0, 255, 170)
        title.Font = Enum.Font.GothamBold
        title.TextSize = 18
        title.Parent = frame

        local info = Instance.new("TextLabel")
        info.Name = "Instructions"
        info.Size = UDim2.new(1, -30, 0, 45)
        info.Position = UDim2.fromOffset(15, 52)
        info.BackgroundTransparency = 1
        info.Text = "Press Z for Enable/Disable Invisible"
        info.TextColor3 = Color3.fromRGB(230, 230, 240)
        info.Font = Enum.Font.GothamMedium
        info.TextSize = 14
        info.TextWrapped = true
        info.Parent = frame

        local hint = Instance.new("TextLabel")
        hint.Name = "CloseHint"
        hint.Size = UDim2.new(1, -30, 0, 22)
        hint.Position = UDim2.fromOffset(15, 101)
        hint.BackgroundTransparency = 1
        hint.Text = "Press OK or Enter to close"
        hint.TextColor3 = Color3.fromRGB(150, 160, 175)
        hint.Font = Enum.Font.Gotham
        hint.TextSize = 12
        hint.Parent = frame

        local okButton = Instance.new("TextButton")
        okButton.Name = "OK"
        okButton.Size = UDim2.fromOffset(100, 32)
        okButton.Position = UDim2.new(0.5, -50, 1, -45)
        okButton.BackgroundColor3 = Color3.fromRGB(0, 150, 110)
        okButton.BorderSizePixel = 0
        okButton.Text = "OK"
        okButton.TextColor3 = Color3.new(1, 1, 1)
        okButton.Font = Enum.Font.GothamBold
        okButton.TextSize = 13
        okButton.Parent = frame

        Instance.new("UICorner", okButton).CornerRadius = UDim.new(0, 8)

        local closed = false
        local enterConnection

        local function closeGuide()
            if closed then return end
            closed = true

            if enterConnection then
                enterConnection:Disconnect()
                enterConnection = nil
            end

            gui:Destroy()
        end

        -- Method 1: Click OK
        okButton.MouseButton1Click:Connect(closeGuide)

        -- Method 2: Press Enter / Numpad Enter
        enterConnection = UserInputService.InputBegan:Connect(function(input)
            if closed then return end

            if input.KeyCode == Enum.KeyCode.Return
                or input.KeyCode == Enum.KeyCode.KeypadEnter then
                closeGuide()
            end
        end)

        gui.Destroying:Connect(function()
            if enterConnection then
                enterConnection:Disconnect()
                enterConnection = nil
            end
        end)
    end

    --// 7. Original Yes / No Prompt
    local function askUser()
        local promptGui = Instance.new("ScreenGui")
        promptGui.Name = "InvisPrompt"
        promptGui.Parent = CoreGui

        local frame = Instance.new("Frame")
        frame.Size = UDim2.fromOffset(250, 120)
        frame.Position = UDim2.new(0.5, -125, 0.15, 0)
        frame.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
        frame.Parent = promptGui

        Instance.new("UICorner", frame)

        local label = Instance.new("TextLabel")
        label.Size = UDim2.new(1, 0, 0.5, 0)
        label.Text = "Do you need Invisible?"
        label.TextColor3 = Color3.new(1, 1, 1)
        label.BackgroundTransparency = 1
        label.Font = Enum.Font.GothamBold
        label.Parent = frame

        local yes = Instance.new("TextButton")
        yes.Size = UDim2.new(0.4, 0, 0.3, 0)
        yes.Position = UDim2.new(0.1, 0, 0.6, 0)
        yes.Text = "Yes"
        yes.BackgroundColor3 = Color3.fromRGB(0, 150, 0)
        yes.TextColor3 = Color3.new(1, 1, 1)
        yes.Parent = frame

        Instance.new("UICorner", yes)

        local no = Instance.new("TextButton")
        no.Size = UDim2.new(0.4, 0, 0.3, 0)
        no.Position = UDim2.new(0.5, 0, 0.6, 0)
        no.Text = "No"
        no.BackgroundColor3 = Color3.fromRGB(150, 0, 0)
        no.TextColor3 = Color3.new(1, 1, 1)
        no.Parent = frame

        Instance.new("UICorner", no)

        yes.MouseButton1Click:Connect(function()
            promptGui:Destroy()
            loadInvisibleAPI()
        end)

        no.MouseButton1Click:Connect(function()
            promptGui:Destroy()
        end)
    end

    --// 8. Start
    if isPCMode then
        -- Load immediately; no original Yes/No prompt or floating button
        loadInvisibleAPI()
        showPCGuide()

        -- Z toggles Invisible in PC Mode
        UserInputService.InputBegan:Connect(function(input, processed)
            if processed then return end

            if input.KeyCode == Enum.KeyCode.Z
                and not invisLoading
                and Invisible then
                setInvisibleState(not invis_on)
            end
        end)
    else
        -- Preserve the original behavior outside PC Mode
        askUser()
    end
end ]]
